insert into public.exam_years (exam_id, subject_id, year, status, published_at) values (1, 1, 2001, 'published', now()) on conflict do nothing;
insert into public.passages (exam_id, subject_id, year, title, body) values (1, 1, 2001, '[SAMPLE] Morning bus', 'Ade woke up before dawn. He packed his books, ate a quick breakfast and left the house early to catch the first bus to school. The road was quiet and the air was cool.');
insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (1, 1, 2001, 1, null, '[SAMPLE] Choose the word nearest in meaning to the word in capitals: The teacher was ADAMANT. (2001)', '{"A": "firm", "B": "angry", "C": "tired", "D": "happy"}'::jsonb, 'A', 'Adamant means refusing to change your mind, so firm is closest.', 'published');
insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (1, 1, 2001, 2, null, '[SAMPLE] Choose the correct option: Neither the boys nor the girl ___ ready.', '{"A": "are", "B": "were", "C": "is", "D": "have"}'::jsonb, 'C', 'With neither/nor the verb agrees with the nearer subject, girl, which is singular.', 'published');
insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (1, 1, 2001, 3, null, '[SAMPLE] Choose the word opposite in meaning to SCARCE.', '{"A": "rare", "B": "plentiful", "C": "small", "D": "costly"}'::jsonb, 'B', 'Scarce means hard to find. Plentiful is the opposite.', 'published');
insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (1, 1, 2001, 4, null, '[SAMPLE] Which word is spelt correctly?', '{"A": "Accomodation", "B": "Acommodation", "C": "Accommodation", "D": "Acomodation"}'::jsonb, 'C', 'Accommodation has double c and double m.', 'published');
insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (1, 1, 2001, 5, (select id from public.passages where exam_id=1 and subject_id=1 and year=2001 and title like '[SAMPLE]%' limit 1), '[SAMPLE] According to the passage, why did Ade leave early?', '{"A": "To catch the first bus", "B": "Because it was raining", "C": "To meet his teacher", "D": "Because he was late"}'::jsonb, 'A', 'The passage says he left early to catch the first bus to school.', 'published');
