insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (1, 3, 2004, 4, null, '[SAMPLE] Sound cannot travel through', '{"A": "water", "B": "steel", "C": "air", "D": "a vacuum"}'::jsonb, 'D', 'Sound needs a medium. A vacuum has none.', 'published');
insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (1, 3, 2004, 5, null, '[SAMPLE] A wire has 12 V across it and 3 A through it. Its resistance is', '{"A": "$4\\,\\Omega$", "B": "$9\\,\\Omega$", "C": "$15\\,\\Omega$", "D": "$36\\,\\Omega$"}'::jsonb, 'A', '$R = \frac{V}{I} = \frac{12}{3} = 4\,\Omega$.', 'published');
insert into public.exam_years (exam_id, subject_id, year, status, published_at) values (1, 4, 2001, 'published', now()) on conflict do nothing;
insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (1, 4, 2001, 1, null, '[SAMPLE] The chemical symbol for sodium is (2001)', '{"A": "S", "B": "So", "C": "Na", "D": "Sd"}'::jsonb, 'C', 'Sodium comes from the Latin natrium, so Na.', 'published');
insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (1, 4, 2001, 2, null, '[SAMPLE] Water ($H_2O$) is made of hydrogen and', '{"A": "nitrogen", "B": "oxygen", "C": "carbon", "D": "chlorine"}'::jsonb, 'B', 'Water is hydrogen and oxygen.', 'published');
insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (1, 4, 2001, 3, null, '[SAMPLE] A solution with pH 2 is', '{"A": "strongly acidic", "B": "neutral", "C": "weakly alkaline", "D": "strongly alkaline"}'::jsonb, 'A', 'pH below 7 is acidic, and 2 is strongly acidic.', 'published');
insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (1, 4, 2001, 4, null, '[SAMPLE] The number of protons in an atom is its', '{"A": "mass number", "B": "atomic number", "C": "valency", "D": "isotope"}'::jsonb, 'B', 'Atomic number = number of protons.', 'published');
insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (1, 4, 2001, 5, null, '[SAMPLE] Which gas is given off when a metal reacts with dilute acid?', '{"A": "Oxygen", "B": "Carbon dioxide", "C": "Hydrogen", "D": "Chlorine"}'::jsonb, 'C', 'Metal + acid gives a salt and hydrogen gas.', 'published');
