insert into public.exam_years (exam_id, subject_id, year, status, published_at) values (2, 2, 2001, 'published', now()) on conflict do nothing;
insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (2, 2, 2001, 1, null, '[SAMPLE] Simplify $\frac{2}{3} + \frac{1}{6}$. (2001)', '{"A": "$\\frac{1}{2}$", "B": "$\\frac{5}{6}$", "C": "$\\frac{3}{9}$", "D": "$1$"}'::jsonb, 'B', '$\frac{2}{3} = \frac{4}{6}$, and $\frac{4}{6} + \frac{1}{6} = \frac{5}{6}$.', 'published');
insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (2, 2, 2001, 2, null, '[SAMPLE] Solve for $x$: $2x + 5 = 17$.', '{"A": "$5$", "B": "$6$", "C": "$7$", "D": "$11$"}'::jsonb, 'B', '$2x = 12$, so $x = 6$.', 'published');
insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (2, 2, 2001, 3, null, '[SAMPLE] Evaluate $\sqrt{144}$.', '{"A": "$11$", "B": "$12$", "C": "$14$", "D": "$72$"}'::jsonb, 'B', '$12 \times 12 = 144$.', 'published');
insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (2, 2, 2001, 4, null, '[SAMPLE] What is 15% of ₦2,000?', '{"A": "₦150", "B": "₦200", "C": "₦300", "D": "₦350"}'::jsonb, 'C', '$0.15 \times 2000 = 300$, so ₦300.', 'published');
insert into public.questions (exam_id, subject_id, year, number, passage_id, body, options, answer, explanation, status) values (2, 2, 2001, 5, null, '[SAMPLE] Find the value of $x^2 - 4$ when $x = 3$.', '{"A": "$2$", "B": "$5$", "C": "$9$", "D": "$13$"}'::jsonb, 'B', '$3^2 - 4 = 9 - 4 = 5$.', 'published');
